fn push_arg_values(
    &self,
    arg: &Arg,
    raw_vals: Vec<OsString>,
    source: ValueSource,
    matcher: &mut ArgMatcher,
) -> ClapResult<()> {
    debug!("Parser::push_arg_values: {raw_vals:?}");

    // The flag-like actions (`SetTrue`, `SetFalse`, `Count`, ...) synthesize their own
    // values (e.g. "true"/"false"/"0") when no value was present on the command line.
    // When those synthetic values are being used to fill in a default (i.e. the user never
    // specified the argument), they shouldn't be run through a user-supplied `value_parser`
    // (e.g. `UnknownArgumentValueParser`) which is only meant to react to actual,
    // user-provided arguments.
    let value_parser = if source == ValueSource::DefaultValue && !arg.get_action().takes_values()
    {
        arg.get_action()
            .default_value_parser()
            .unwrap_or_else(|| arg.get_value_parser().clone())
    } else {
        arg.get_value_parser().clone()
    };

    for raw_val in raw_vals {
        // update the current index because each value is a distinct index to clap
        self.cur_idx.set(self.cur_idx.get() + 1);
        debug!(
            "Parser::add_single_val_to_arg: cur_idx:={}",
            self.cur_idx.get()
        );
        let val = ok!(value_parser.parse_ref(self.cmd, Some(arg), &raw_val));

        matcher.add_val_to(arg.get_id(), val, raw_val);
        matcher.add_index_to(arg.get_id(), self.cur_idx.get());
    }

    Ok(())
}

